function updateMedicineUnits(){const form=dialog.querySelector('#add-medicine-form'),medicine=snapshot.medicines.find(m=>m.id===form.elements.medicineId.value);form.elements.unit.innerHTML=options(medicine?allowedMedicineUnits(medicine.medicineForm).map(u=>[u,u==='впрыскивание'?'пшик':u]):[],'');form.querySelector('#add-medicine-inhalation').hidden=medicine?.medicineForm!=='inhalation';}
async function saveSlotMedicine(form){
  const person=snapshot.model.cards.find(p=>p.id===form.elements.personId.value),medicine=snapshot.medicines.find(m=>m.id===form.elements.medicineId.value),anchorsSelected=[...form.querySelectorAll('[name=slot]:checked')].map(n=>n.value),dose=form.elements.dose.value.replace(',','.').trim(),days=form.elements.days.value,relation=form.elements.relation.value;
  if(!person||!medicine||medicine.archived)throw Error('Выберите человека и препарат');if(!/^\d+(?:\.\d+)?$/.test(dose)||Number(dose)<=0)throw Error('Укажите разовую дозу');if(!anchorsSelected.length)throw Error('Выберите хотя бы один слот');
  const slots=availableMedicineSlots(person);for(const anchor of anchorsSelected){const slot=slots.find(s=>s.anchor===anchor);if(!slot||(days==='all'?slot.days.length!==2:!slot.days.includes(days)))throw Error('Выбранный слот доступен не во все указанные дни. Измените дни в дополнительных параметрах.');}
  const body={personId:person.id,medicineId:medicine.id,medicineVersion:medicine.version,manualKey:form.dataset.key,name:medicine.name,medicineForm:medicine.medicineForm,strength:medicine.strength,dose,unit:form.elements.unit.value,type:'routine',routineSlots:anchorsSelected.map(anchor=>({anchor,relation})),...(days!=='all'?{weekdays:days==='weekday'?[1,2,3,4,5]:[0,6]}:{}),startDate:form.elements.startDate.value,endDate:form.elements.endDate.value,carePhase:form.elements.carePhase.value,conditions:form.elements.conditions.value,timeZone:snapshot.timeZone,confirmed:true,sourceText:'',documentId:'',regimen:{origin:'manual',...(medicine.medicineForm==='inhalation'?{mixing:form.elements.mixing.value,durationMinutes:form.elements.durationMinutes.value}:{})}};
  const result=await mutate('/prescriptions',body,'POST',{success:'Лекарство добавлено в слот'});if(result&&snapshot){if(selected!=='all'){selected=person.id;localStorage.setItem('medika-family-person',selected);}earlierOpen.add(person.id);render();const row=baseRows().find(r=>r.prescriptionId===result.id),node=[...root.querySelectorAll('[data-demo-row]')].find(n=>n.dataset.demoRow===row?.key)||[...root.querySelectorAll('[data-edit]')].find(n=>n.dataset.edit===result.id);node?.scrollIntoView({block:'nearest'});}
}

