  if(form.id==='correction-form'){const entry=snapshot.model.history.find(r=>r.id===form.dataset.id);const changes={...readWhen(form,entry.input),version:Number(form.dataset.version),note:form.elements.note.value,...(form.elements.celsius?{celsius:form.elements.celsius.value}:{}),...(form.elements.amount?{amount:form.elements.amount.value.replace(',','.')}:{} )};await mutate('/'+entry.source+'/'+entry.id+'/correct',changes,'POST',{success:'Исправление сохранено'});return;}
